import{_ as t,o,c as a,a2 as s}from"./chunks/framework.Desnpdez.js";const r="/mbit-mcpo-proxy-download/guide/images/settings-license-gateway.png",n="/mbit-mcpo-proxy-download/guide/images/settings-import-analyze.png",m=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"everyday/settings.md","filePath":"everyday/settings.md"}'),i={name:"everyday/settings.md"};function l(d,e,c,h,g,p){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p><strong>Settings</strong> covers your <strong>license</strong>, the <strong>assistant bridge</strong> port, where files live on disk, <strong>OAuth</strong> resets, and optional <strong>JSON import</strong>.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><ul><li>Paste a new key and tap <strong>Save &amp; validate</strong> when your subscription changes.</li><li><strong>Re-check now</strong> forces an online validation.</li><li><strong>Remove stored key</strong> signs you out of the licensed features.</li></ul><p>The full key is never shown—only a short suffix.</p><p><img src="'+r+'" alt="License and gateway settings"></p><h2 id="gateway" tabindex="-1">Gateway <a class="header-anchor" href="#gateway" aria-label="Permalink to &quot;Gateway&quot;">​</a></h2><ul><li><strong>Advanced mode</strong> — shows technical names (for example raw transport labels) and extra tools such as viewing generated config. Leave off unless support asks you to turn it on.</li><li><strong>HTTP port on this computer</strong> — every <strong>Copy link</strong> URL uses this port (default <strong>8000</strong>). Changing it restarts the bridge.</li></ul><p>Tap <strong>Save settings</strong> after edits.</p><h2 id="data-directory" tabindex="-1">Data Directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data Directory&quot;">​</a></h2><p>Shows the folder where MindBehindAI stores <code>servers.json</code>, generated config, and related files. <strong>Open</strong> jumps to it in Finder.</p><h2 id="privacy-and-security" tabindex="-1">Privacy and security <a class="header-anchor" href="#privacy-and-security" aria-label="Permalink to &quot;Privacy and security&quot;">​</a></h2><h3 id="oauth-tokens" tabindex="-1">OAuth tokens <a class="header-anchor" href="#oauth-tokens" aria-label="Permalink to &quot;OAuth tokens&quot;">​</a></h3><p>Saved sign-ins keep Telekom, Microsoft, and similar logins working between app restarts. Clear tokens if you switched accounts, something expired, or you want a clean login.</p><p>Sign-in always happens in your <strong>normal web browser</strong>, not inside the small MindBehind window.</p><p>The same <strong>Settings</strong> scroll also contains <strong>Import configuration</strong> (below). This screenshot shows <strong>OAuth tokens</strong> and the <strong>Import</strong> area together—use <strong>Clear OAuth tokens</strong> here, and scroll to the JSON box for the next section.</p><p><img src="'+n+'" alt="Settings — OAuth tokens and JSON import (same page, scroll)"></p><h2 id="import-json-mcp-json" tabindex="-1">Import JSON (<code>mcp.json</code>) <a class="header-anchor" href="#import-json-mcp-json" aria-label="Permalink to &quot;Import JSON (`mcp.json`)&quot;">​</a></h2><p>For migrating from another MCP host:</p><ol><li>Paste JSON in the usual shape (<code>mcpServers</code> or <code>servers</code>, optional <code>inputs</code> and <code>${input:id}</code> placeholders).</li><li>Tap <strong>Analyze</strong> (bottom of the Import area in the screenshot above).</li></ol><p>This path is aimed at power users. Everyone else should use <strong>Connections → Library</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><strong><a href="./../reference/data-directory.html">Data directory</a></strong> — detailed file list.</li><li><strong><a href="./../reference/import-json.html">Import JSON reference</a></strong> — format notes.</li><li><strong><a href="./../reference/advanced-mode.html">Advanced mode</a></strong> — what changes when the checkbox is on.</li></ul>',23)])])}const f=t(i,[["render",l]]);export{m as __pageData,f as default};
